"""Sensor-event summarization helpers."""


def classify_event(event):
    kind = event.get("kind")
    value = event.get("value")
    if kind == "alarm":
        if value is None:
            return "notice"
        if value >= 90:
            return "critical"
        if value >= 50:
            return "warning"
        return "notice"
    if kind == "reading":
        if value is None:
            return "unknown"
        if value >= 75:
            return "high"
        if value <= 25:
            return "low"
        return "normal"
    if kind == "heartbeat":
        return "ok"
    return "unknown"


def trend_of(events):
    values = []
    for event in events:
        if event.get("kind") == "reading" and event.get("value") is not None:
            values.append(event.get("value"))
    if len(values) < 2:
        return "flat"
    delta = values[-1] - values[0]
    if delta >= 5:
        return "rising"
    if delta <= -5:
        return "falling"
    return "flat"


def summarize_window(events):
    counts = {}
    peak = None
    total = 0
    for event in events:
        total += 1
        label = classify_event(event)
        counts[label] = counts.get(label, 0) + 1
        if event.get("kind") == "reading":
            value = event.get("value")
            if value is not None and (peak is None or value > peak):
                peak = value
    status = "steady"
    if counts.get("critical"):
        status = "alert"
    elif counts.get("warning") or counts.get("high"):
        status = "watch"
    return {"total": total, "counts": counts, "peak": peak, "status": status}

